import React, { useEffect, useRef, useState } from "react";

// ─── ANIMATED PROGRESS BAR ────────────────────────────────────────────────────
function ProgressBar({ value, color = "#34d399", label, sublabel, delay = 0 }) {
  const [width, setWidth] = useState(0);

  useEffect(() => {
    const timer = setTimeout(() => setWidth(value), 120 + delay);
    return () => clearTimeout(timer);
  }, [value, delay]);

  return (
    <div className="mb-4">
      <div className="flex items-center justify-between mb-1.5">
        <span className="text-sm text-slate-400">{label}</span>
        <div className="flex items-center gap-2">
          {sublabel && <span className="text-xs text-slate-600">{sublabel}</span>}
          <span
            className="number-display text-base font-bold"
            style={{ color }}
          >
            {value}%
          </span>
        </div>
      </div>
      <div className="stat-bar">
        <div
          className="stat-bar-fill"
          style={{
            width: `${width}%`,
            background: `linear-gradient(90deg, ${color}80, ${color})`,
          }}
        />
      </div>
    </div>
  );
}

// ─── SCORE MATRIX CELL ────────────────────────────────────────────────────────
function MatrixCell({ prob, isHighest }) {
  const opacity = Math.max(0.08, prob * 4);
  return (
    <div
      className={`relative flex items-center justify-center rounded text-xs number-display ${
        isHighest
          ? "ring-1 ring-emerald-400 bg-emerald-500/20 text-emerald-300 font-bold"
          : "text-slate-500"
      }`}
      style={{
        minWidth: 36,
        minHeight: 32,
        background: isHighest
          ? undefined
          : `rgba(52, 211, 153, ${opacity})`,
        fontSize: 10,
      }}
      title={`${(prob * 100).toFixed(1)}%`}
    >
      {(prob * 100).toFixed(1)}
    </div>
  );
}

// ─── SCORE MATRIX ─────────────────────────────────────────────────────────────
function ScoreMatrix({ matrix, mostLikelyScore, homeTeam, awayTeam }) {
  if (!matrix) return null;

  const [mh, ma] = mostLikelyScore.split("-").map(Number);

  const goals = [0, 1, 2, 3, 4, 5];

  return (
    <div className="overflow-x-auto">
      <table className="w-full text-center" style={{ borderCollapse: "separate", borderSpacing: 3 }}>
        <thead>
          <tr>
            <th className="text-xs text-slate-600 p-1 text-right" style={{ minWidth: 60 }}>
              <span className="text-slate-500">L\V</span>
            </th>
            {goals.map((g) => (
              <th key={g} className="text-xs text-slate-600 p-1" style={{ minWidth: 36 }}>
                {g}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {goals.map((h) => (
            <tr key={h}>
              <td className="text-xs text-slate-600 p-1 text-right pr-2">{h}</td>
              {goals.map((a) => (
                <td key={a} className="p-0.5">
                  <MatrixCell
                    prob={matrix[h]?.[a] || 0}
                    isHighest={h === mh && a === ma}
                  />
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
      <div className="flex items-center gap-2 mt-2 text-xs text-slate-600">
        <div className="w-3 h-3 rounded-sm bg-emerald-500/20 ring-1 ring-emerald-400" />
        <span>Resultado más probable</span>
        <span className="ml-auto">Filas = Goles Local | Cols = Goles Visitante</span>
      </div>
    </div>
  );
}

// ─── DATA QUALITY INDICATOR ───────────────────────────────────────────────────
function DataQualityBadge({ quality }) {
  const configs = {
    full: { label: "Datos Completos", color: "text-emerald-400", bg: "bg-emerald-500/10", border: "border-emerald-500/30" },
    partial: { label: "Datos Parciales", color: "text-amber-400", bg: "bg-amber-500/10", border: "border-amber-500/30" },
    estimated: { label: "Datos Estimados", color: "text-orange-400", bg: "bg-orange-500/10", border: "border-orange-500/30" },
  };
  const c = configs[quality] || configs.estimated;
  return (
    <span className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full border text-xs ${c.color} ${c.bg} ${c.border}`}>
      <div className={`w-1.5 h-1.5 rounded-full ${c.color.replace("text-", "bg-")}`} />
      {c.label}
    </span>
  );
}

// ─── STAT PILL ────────────────────────────────────────────────────────────────
function StatPill({ label, value, color }) {
  return (
    <div className="flex flex-col items-center p-3 rounded-lg bg-slate-800/60 border border-slate-700/50">
      <span className="number-display text-xl font-bold" style={{ color: color || "#e2e8f0" }}>
        {value}
      </span>
      <span className="text-slate-600 text-xs mt-0.5 text-center">{label}</span>
    </div>
  );
}

// ─── MAIN MODAL ───────────────────────────────────────────────────────────────
export default function PredictionModal({ match, onClose }) {
  const backdropRef = useRef(null);

  useEffect(() => {
    document.body.style.overflow = "hidden";
    const handleEsc = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", handleEsc);
    return () => {
      document.body.style.overflow = "";
      window.removeEventListener("keydown", handleEsc);
    };
  }, [onClose]);

  if (!match) return null;

  const mc = match.monteCarlo;
  const str = match.strengths;

  function handleBackdropClick(e) {
    if (e.target === backdropRef.current) onClose();
  }

  return (
    <div
      ref={backdropRef}
      className="fixed inset-0 z-50 flex items-center justify-center p-4 animate-fade-in"
      style={{ background: "rgba(8, 15, 28, 0.85)", backdropFilter: "blur(6px)" }}
      onClick={handleBackdropClick}
    >
      <div
        className="w-full max-w-2xl max-h-[90vh] overflow-y-auto rounded-2xl animate-scale-in"
        style={{
          background: "linear-gradient(160deg, #0f172a 0%, #0c1629 100%)",
          border: "1px solid rgba(51, 65, 85, 0.6)",
          boxShadow: "0 40px 80px rgba(0,0,0,0.6), 0 0 60px rgba(52,211,153,0.05)",
        }}
      >
        {/* Header */}
        <div className="sticky top-0 z-10 flex items-start justify-between p-6 pb-4"
          style={{ background: "linear-gradient(160deg, #0f172a, #0c1629)", borderBottom: "1px solid rgba(51,65,85,0.3)" }}
        >
          <div>
            <div className="flex items-center gap-2 mb-1">
              <span className="text-slate-500 text-xs uppercase tracking-widest">{match.competition}</span>
              <DataQualityBadge quality={match.dataQuality} />
            </div>
            <h2 className="display-font text-2xl text-white tracking-wide">
              {match.homeTeam}
              <span className="text-slate-600 mx-3">vs</span>
              {match.awayTeam}
            </h2>
            <div className="flex items-center gap-4 mt-1 text-xs text-slate-600">
              <span>Monte Carlo: <span className="text-slate-400 number-display">{mc?.iterations?.toLocaleString()}</span> iteraciones</span>
              <span>xG Local: <span className="text-emerald-400 number-display">{match.expectedGoals?.home}</span></span>
              <span>xG Visitante: <span className="text-emerald-400 number-display">{match.expectedGoals?.away}</span></span>
            </div>
          </div>
          <button
            onClick={onClose}
            className="ml-4 text-slate-600 hover:text-slate-300 transition-colors p-2 rounded-lg hover:bg-slate-800/60"
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        {/* Body */}
        <div className="p-6 space-y-6">

          {/* Confidence + Poisson score */}
          <div className="grid grid-cols-3 gap-3">
            <StatPill
              label="Índice de Confianza"
              value={`${mc?.confidenceIndex}%`}
              color={mc?.confidenceIndex >= 75 ? "#34d399" : mc?.confidenceIndex >= 55 ? "#fbbf24" : "#f87171"}
            />
            <StatPill
              label="Resultado Poisson"
              value={match.mostLikelyScore}
              color="#34d399"
            />
            <StatPill
              label="Prob. Resultado"
              value={`${match.topScoreProb}%`}
              color="#94a3b8"
            />
          </div>

          {/* 1X2 Probabilities */}
          <div className="glass-panel rounded-xl p-4">
            <h3 className="display-font text-base text-slate-400 mb-4 tracking-widest">
              RESULTADO FINAL (1X2)
            </h3>
            <ProgressBar
              value={mc?.homeWin || 0}
              color="#60a5fa"
              label={`${match.homeTeam} (Local)`}
              sublabel="1"
              delay={0}
            />
            <ProgressBar
              value={mc?.draw || 0}
              color="#94a3b8"
              label="Empate"
              sublabel="X"
              delay={100}
            />
            <ProgressBar
              value={mc?.awayWin || 0}
              color="#a78bfa"
              label={`${match.awayTeam} (Visitante)`}
              sublabel="2"
              delay={200}
            />
          </div>

          {/* Secondary markets */}
          <div className="grid grid-cols-2 gap-4">
            {/* BTTS */}
            <div className="glass-panel rounded-xl p-4">
              <h3 className="display-font text-sm text-slate-400 mb-3 tracking-widest">
                AMBOS ANOTAN
              </h3>
              <ProgressBar
                value={mc?.bttsYes || 0}
                color="#34d399"
                label="Sí"
                delay={300}
              />
              <ProgressBar
                value={mc?.bttsNo || 0}
                color="#f87171"
                label="No"
                delay={400}
              />
            </div>

            {/* Over/Under */}
            <div className="glass-panel rounded-xl p-4">
              <h3 className="display-font text-sm text-slate-400 mb-3 tracking-widest">
                TOTAL GOLES (2.5)
              </h3>
              <ProgressBar
                value={mc?.over25 || 0}
                color="#fbbf24"
                label="Más de 2.5"
                delay={300}
              />
              <ProgressBar
                value={mc?.under25 || 0}
                color="#64748b"
                label="Menos de 2.5"
                delay={400}
              />
              <div className="mt-2 text-xs text-slate-600">
                Promedio proyectado:{" "}
                <span className="text-slate-400 number-display">{mc?.avgGoals}</span> goles
              </div>
            </div>
          </div>

          {/* Score Matrix */}
          {match.scoreMatrix && (
            <div className="glass-panel rounded-xl p-4">
              <h3 className="display-font text-base text-slate-400 mb-4 tracking-widest">
                MATRIZ DE MARCADORES (POISSON)
              </h3>
              <ScoreMatrix
                matrix={match.scoreMatrix}
                mostLikelyScore={match.mostLikelyScore}
                homeTeam={match.homeTeam}
                awayTeam={match.awayTeam}
              />
            </div>
          )}

          {/* Team Strengths */}
          {str && (
            <div className="glass-panel rounded-xl p-4">
              <h3 className="display-font text-base text-slate-400 mb-4 tracking-widest">
                ÍNDICES DE FUERZA
              </h3>
              <div className="grid grid-cols-2 gap-6">
                {/* Home */}
                <div>
                  <div className="text-sm text-slate-400 mb-3 font-semibold">{match.homeTeam}</div>
                  <div className="space-y-2 text-xs">
                    <div className="flex items-center justify-between">
                      <span className="text-slate-600">Ataque</span>
                      <div className="flex items-center gap-2">
                        <div className="w-16 h-1 rounded-full bg-slate-800 overflow-hidden">
                          <div
                            className="h-full rounded-full bg-blue-400"
                            style={{ width: `${Math.min(100, str.home?.attack * 50)}%` }}
                          />
                        </div>
                        <span className="number-display text-blue-400">{str.home?.attack}</span>
                      </div>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-slate-600">Defensa</span>
                      <div className="flex items-center gap-2">
                        <div className="w-16 h-1 rounded-full bg-slate-800 overflow-hidden">
                          <div
                            className="h-full rounded-full bg-blue-400"
                            style={{ width: `${Math.min(100, str.home?.defense * 50)}%` }}
                          />
                        </div>
                        <span className="number-display text-blue-400">{str.home?.defense}</span>
                      </div>
                    </div>
                    <div className="text-slate-700 mt-1">
                      <span>{str.home?.gamesAnalyzed} partidos analizados</span>
                    </div>
                  </div>
                </div>

                {/* Away */}
                <div>
                  <div className="text-sm text-slate-400 mb-3 font-semibold">{match.awayTeam}</div>
                  <div className="space-y-2 text-xs">
                    <div className="flex items-center justify-between">
                      <span className="text-slate-600">Ataque</span>
                      <div className="flex items-center gap-2">
                        <div className="w-16 h-1 rounded-full bg-slate-800 overflow-hidden">
                          <div
                            className="h-full rounded-full bg-purple-400"
                            style={{ width: `${Math.min(100, str.away?.attack * 50)}%` }}
                          />
                        </div>
                        <span className="number-display text-purple-400">{str.away?.attack}</span>
                      </div>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-slate-600">Defensa</span>
                      <div className="flex items-center gap-2">
                        <div className="w-16 h-1 rounded-full bg-slate-800 overflow-hidden">
                          <div
                            className="h-full rounded-full bg-purple-400"
                            style={{ width: `${Math.min(100, str.away?.defense * 50)}%` }}
                          />
                        </div>
                        <span className="number-display text-purple-400">{str.away?.defense}</span>
                      </div>
                    </div>
                    <div className="text-slate-700 mt-1">
                      <span>{str.away?.gamesAnalyzed} partidos analizados</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Disclaimer */}
